@Component("user-handler")
@ProcessingGroup("user-processing-group")
public class UserEventHandler {
	
	// core constructor
	UserEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateUserEvent
     */
    @EventHandler
    public void handle( CreateUserEvent event) {
        entityManager.persist(new User(event.getUserId(), event.getFirstName(), event.getLastName(), event.getEmail(), event.getAgency(), event.getTeams(), event.getAdAccounts(), event.getRole()));
    }

    /*
     * @param	event UpdateUserEvent
     */
    @EventHandler
    public User handle( UpdateUserEvent event) {
    	entityManager.merge(new User(event.getUserId(), event.getFirstName(), event.getLastName(), event.getEmail(), event.getAgency(), event.getTeams(), event.getAdAccounts(), event.getRole()));
    }
    
    /*
     * @param	event DeleteUserEvent
     */
    @EventHandler
    public void on( DeleteUserEvent event) {
    	User entity = new User();
   
    	// ------------------------------------------
    	// apply the UserId
    	// ------------------------------------------
    	entity.setUserId( event.getUserId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final UserRepository userEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(UserEventHandler.class.getName());

}
